class RiverBankWidthTest{static int banks(double width){int n=256;var e=new EnvironmentMap(EnvironmentMap.filled(n*n,100));e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];for(int z=0;z<n;z++)for(int x=120;x<=136;x++){int i=z*n+x;e.height[i]=82;e.water[i]=86;e.river[i]=1;}var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVER_BANKS,0,0);node.values.put("width",width);node.values.put("reach",224.0);RiverBanks.gradeValley(node,e,n,n,62,2024,0,0,()->false);int count=0;for(int i=0;i<n*n;i++)if(e.waterY(i,62)<=Math.round(e.height[i])&&(e.material[i]==5||e.material[i]==7||e.material[i]==10))count++;return count;}public static void main(String[]args){int narrow=banks(18),wide=banks(40);if(wide<narrow*1.35)throw new AssertionError("Wider bank setting did not expand deposits: "+narrow+" / "+wide);System.out.println("PASS: wider bank setting expands irregular sediment and dirt footprint "+narrow+" -> "+wide);}}
